namespace Aster {
static class Program {
 [STAThread] static void Main(string[] args) {
  if(args.Length>0 && args[0]=="--self-test") { if(args.Length<2){Environment.ExitCode=2;return;} try { var c=new Collector();c.Sample();System.Threading.Thread.Sleep(1100);var s=c.Sample();if(s.Total<=0||s.Processes.Count==0||s.Cpu<0||s.Cpu>100)throw new Exception("Invalid system sample");foreach(var name in new[]{"System info","CPU specs","Memory specs","Storage specs","Motherboard & BIOS","Network adapters","Services","Startup apps","Disk space","Connections","Installed apps","Drivers","Users","GPU"}){var t=Inventory.Read(name);if(t.Columns.Length==0)throw new Exception(name+" has no schema");}File.WriteAllText(args[1],"PASS: CPU sampling, memory, process enumeration and inventory schemas (provider availability may be restricted).\r\nCPU: "+s.Cpu.ToString("F1")+"%; RAM: "+(s.Total/1073741824.0).ToString("F1")+" GB; processes: "+s.Processes.Count+"\r\n");return;}catch(Exception ex){File.WriteAllText(args[1],"FAIL: "+ex);Environment.ExitCode=1;return;} }
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);if(args.Length==2&&args[0]=="--repair"){var job=RecoveryJob.Find(args[1]);if(job==null){MessageBox.Show("Unknown recovery tool.");return;}Application.Run(new RepairWindow(job));return;}if(args.Length==2&&args[0]=="--plan"){var plan=RepairPlan.Find(args[1]);if(plan==null){MessageBox.Show("Unknown repair plan.");return;}Application.Run(new PlanWindow(plan));return;}StartupLauncher.Run();
 }
}
static class Native {
 [StructLayout(LayoutKind.Sequential)] public struct Times {public uint Low,High;public ulong Value{get{return ((ulong)High<<32)|Low;}}}
 [StructLayout(LayoutKind.Sequential)] public class Memory {public uint Length=(uint)Marshal.SizeOf(typeof(Memory));public uint Load;public ulong Total,Available,TotalPage,AvailPage,TotalVirtual,AvailVirtual,AvailExtended;}
 [DllImport("kernel32.dll")] public static extern bool GetSystemTimes(out Times idle,out Times kernel,out Times user);
 [DllImport("kernel32.dll",SetLastError=true)] public static extern bool GlobalMemoryStatusEx([In,Out] Memory value);
 [DllImport("kernel32.dll")] public static extern ulong GetTickCount64();
 [DllImport("kernel32.dll",SetLastError=true)] public static extern bool IsProcessCritical(IntPtr process,out bool critical);
}
class Proc {public int Id,Threads,Handles,Session;public string Name;public double Cpu;public long Memory,Start;}
class Snapshot {public double Cpu,MemoryPercent,Receive,Send,DiskRead,DiskWrite,Gpu;public ulong Total,Available;public List<Proc> Processes=new List<Proc>();public DateTime Time=DateTime.Now;public string Warning="";}
class Collector {
 ulong idle,kernel,user;bool primed;long stamp;Dictionary<int,Tuple<double,long>> previous=new Dictionary<int,Tuple<double,long>>();Dictionary<string,Tuple<long,long>> network=new Dictionary<string,Tuple<long,long>>();
 public Snapshot Sample(){var s=new Snapshot();var now=Stopwatch.GetTimestamp();double elapsed=stamp==0?0:(now-stamp)/(double)Stopwatch.Frequency;stamp=now;Native.Times i,k,u;if(Native.GetSystemTimes(out i,out k,out u)){ulong all=k.Value+u.Value,prior=kernel+user;if(primed&&all>prior)s.Cpu=Math.Max(0,Math.Min(100,100.0*(1-(i.Value-idle)/(double)(all-prior))));idle=i.Value;kernel=k.Value;user=u.Value;primed=true;}
 var mem=new Native.Memory();if(!Native.GlobalMemoryStatusEx(mem))throw new Win32Exception();s.Total=mem.Total;s.Available=mem.Available;s.MemoryPercent=100.0*(mem.Total-mem.Available)/mem.Total;
 var next=new Dictionary<int,Tuple<double,long>>();foreach(var p in Process.GetProcesses()){using(p){try{var row=new Proc{Id=p.Id,Name=p.ProcessName,Memory=p.WorkingSet64,Session=p.SessionId};double cpu=0;try{cpu=p.TotalProcessorTime.TotalSeconds;row.Start=p.StartTime.ToUniversalTime().Ticks;Tuple<double,long> last;if(elapsed>0&&previous.TryGetValue(p.Id,out last)&&last.Item2==row.Start)row.Cpu=Math.Max(0,Math.Min(100,(cpu-last.Item1)/elapsed/Environment.ProcessorCount*100));next[p.Id]=Tuple.Create(cpu,row.Start);}catch{}try{row.Threads=p.Threads.Count;row.Handles=p.HandleCount;}catch{}s.Processes.Add(row);}catch{}}}previous=next;
 var nn=new Dictionary<string,Tuple<long,long>>();foreach(var n in NetworkInterface.GetAllNetworkInterfaces()){try{if(n.OperationalStatus!=OperationalStatus.Up||n.NetworkInterfaceType==NetworkInterfaceType.Loopback)continue;var st=n.GetIPv4Statistics();Tuple<long,long> last;if(elapsed>0&&network.TryGetValue(n.Id,out last)){s.Receive+=Math.Max(0,st.BytesReceived-last.Item1)/elapsed;s.Send+=Math.Max(0,st.BytesSent-last.Item2)/elapsed;}nn[n.Id]=Tuple.Create(st.BytesReceived,st.BytesSent);}catch{}}network=nn;
 s.DiskRead=double.NaN;s.DiskWrite=double.NaN;s.Gpu=double.NaN;
 try{using(var search=new ManagementObjectSearcher("SELECT DiskReadBytesPersec,DiskWriteBytesPersec FROM Win32_PerfFormattedData_PerfDisk_PhysicalDisk WHERE Name='_Total'")){foreach(ManagementObject o in search.Get()){using(o){s.DiskRead=Convert.ToDouble(o["DiskReadBytesPersec"]);s.DiskWrite=Convert.ToDouble(o["DiskWriteBytesPersec"]);}}}}catch{s.Warning="Disk counters unavailable";}
 return s;
 }
}
class Table {public string[] Columns;public List<string[]> Rows=new List<string[]>();public string Note="";public Table(params string[] columns){Columns=columns;}}
static partial class Inventory {
 static string S(object v){return v==null?"Unavailable":Convert.ToString(v);}
 static void Wmi(Table t,string query,params string[] keys){using(var q=new ManagementObjectSearcher(query)){q.Options.Timeout=TimeSpan.FromSeconds(12);foreach(ManagementObject o in q.Get()){using(o){t.Rows.Add(keys.Select(k=>S(o[k])).ToArray());}}}}
 public static Table Read(string name){if(new[]{"CPU specs","Memory specs","Storage specs","Motherboard & BIOS","Network adapters","GPU"}.Contains(name))return Hardware(name);Table t;try{switch(name){
 case "Services":t=new Table("Name","Display name","Status","Start mode","PID");Wmi(t,"SELECT Name,DisplayName,State,StartMode,ProcessId FROM Win32_Service","Name","DisplayName","State","StartMode","ProcessId");t.Note="Read-only service inventory. Use Windows Services for configuration.";break;
 case "Startup apps":t=new Table("Name","Command","Location","User");Wmi(t,"SELECT Name,Command,Location,User FROM Win32_StartupCommand","Name","Command","Location","User");t.Note="Registered startup commands; scheduled tasks and all packaged-app startup entries are not included.";break;
 case "Drivers":t=new Table("Name","Display name","State","Start mode","Path");Wmi(t,"SELECT Name,DisplayName,State,StartMode,PathName FROM Win32_SystemDriver","Name","DisplayName","State","StartMode","PathName");break;
 case "GPU":t=new Table("Adapter","Driver version","Video processor","Display mode");Wmi(t,"SELECT Name,DriverVersion,VideoProcessor,VideoModeDescription FROM Win32_VideoController","Name","DriverVersion","VideoProcessor","VideoModeDescription");t.Note="GPU identification. Temperature, board power and CPU package power need vendor sensor support and are not available here.";break;
 case "Users":t=new Table("Account","Domain","Status","SID");Wmi(t,"SELECT Name,Domain,Status,SID FROM Win32_UserAccount WHERE LocalAccount=True","Name","Domain","Status","SID");t.Note="Local user accounts, not a list of active login sessions.";break;
 case "Connections":t=new Table("Protocol","Local endpoint","Remote endpoint","State");var ip=IPGlobalProperties.GetIPGlobalProperties();foreach(var x in ip.GetActiveTcpConnections())t.Rows.Add(new[]{"TCP",x.LocalEndPoint.ToString(),x.RemoteEndPoint.ToString(),x.State.ToString()});foreach(var x in ip.GetActiveTcpListeners())t.Rows.Add(new[]{"TCP",x.ToString(),"—","Listening"});foreach(var x in ip.GetActiveUdpListeners())t.Rows.Add(new[]{"UDP",x.ToString(),"—","Bound"});t.Note="Current endpoints on this computer. Process ownership is not provided.";break;
 case "Disk space":t=new Table("Drive","Label","Format","Capacity","Free","Used");foreach(var d in DriveInfo.GetDrives()){try{if(d.IsReady)t.Rows.Add(new[]{d.Name,d.VolumeLabel,d.DriveFormat,Bytes(d.TotalSize),Bytes(d.AvailableFreeSpace),(100.0*(d.TotalSize-d.TotalFreeSpace)/d.TotalSize).ToString("F1")+"%"});}catch{}}t.Note="Mounted volumes. Drive health / SMART is not inferred from free space.";break;
 case "Installed apps":t=new Table("Application","Version","Publisher","Installed");var seen=new HashSet<string>();foreach(var hive in new[]{RegistryHive.LocalMachine,RegistryHive.CurrentUser})foreach(var rv in new[]{RegistryView.Registry64,RegistryView.Registry32}){using(var root=RegistryKey.OpenBaseKey(hive,rv))using(var key=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall")){if(key==null)continue;foreach(var sub in key.GetSubKeyNames()){using(var k=root.OpenSubKey(@"SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\"+sub)){if(k==null)continue;string n=S(k.GetValue("DisplayName")),v=S(k.GetValue("DisplayVersion"));if(n=="Unavailable"||!seen.Add(n+v))continue;t.Rows.Add(new[]{n,v,S(k.GetValue("Publisher")),S(k.GetValue("InstallDate"))});}}}}t.Note="Desktop applications registered for uninstall; some Microsoft Store apps may not appear.";break;
 default:t=new Table("Property","Value");t.Rows.Add(new[]{"Computer",Environment.MachineName});t.Rows.Add(new[]{"Current user",Environment.UserDomainName+"\\"+Environment.UserName});t.Rows.Add(new[]{"Logical processors",Environment.ProcessorCount.ToString()});t.Rows.Add(new[]{"Process architecture",Environment.Is64BitProcess?"64-bit":"32-bit"});using(var q=new ManagementObjectSearcher("SELECT Caption,Version,OSArchitecture,LastBootUpTime FROM Win32_OperatingSystem")){foreach(ManagementObject o in q.Get()){using(o){foreach(var key in new[]{"Caption","Version","OSArchitecture","LastBootUpTime"})t.Rows.Add(new[]{key,S(o[key])});}}}using(var q=new ManagementObjectSearcher("SELECT Name,NumberOfCores,NumberOfLogicalProcessors,MaxClockSpeed FROM Win32_Processor")){foreach(ManagementObject o in q.Get()){using(o){foreach(var key in new[]{"Name","NumberOfCores","NumberOfLogicalProcessors","MaxClockSpeed"})t.Rows.Add(new[]{"CPU "+key,S(o[key])});}}}t.Note="Clock values from firmware are in MHz and may differ from live boost frequencies.";break;
 }return t;}catch(Exception ex){t=new Table("Status","Details");t.Rows.Add(new[]{"Provider unavailable",ex.Message});t.Note="Windows may restrict this data. No estimated or simulated values are substituted.";return t;}}
 public static string Bytes(double n){if(double.IsNaN(n))return "Unavailable";string[] u={"B","KB","MB","GB","TB"};int i=0;while(n>=1024&&i<u.Length-1){n/=1024;i++;}return n.ToString(i>1?"F1":"F0")+" "+u[i];}
}
class Graph:Control {
 public List<double> Values=new List<double>();public Color Accent=Color.FromArgb(55,197,231);public string Caption="CPU",Value="Waiting for sample",Hint="";public double Ceiling=100;public bool AutoScale;
 public Graph(){DoubleBuffered=true;BackColor=Color.FromArgb(24,29,37);ForeColor=Color.White;MinimumSize=new Size(150,100);}
 public void Add(double v){Values.Add(v);if(Values.Count>60)Values.RemoveAt(0);Invalidate();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;var r=new Rectangle(18,64,Math.Max(1,Width-36),Math.Max(1,Height-91));using(var title=new Font("Segoe UI",10,FontStyle.Bold))using(var big=new Font("Segoe UI",19))using(var dim=new SolidBrush(ThemePalette.Current.Muted))using(var text=new SolidBrush(ForeColor)){g.DrawString(Caption,title,text,18,13);var sz=g.MeasureString(Value,big);using(var accentBrush=new SolidBrush(Accent))g.DrawString(Value,big,accentBrush,Width-sz.Width-18,12);g.DrawString(Hint,Font,dim,18,Height-23);}
 using(var p=new Pen(ThemePalette.Current.Border)){for(int x=0;x<=10;x++)g.DrawLine(p,r.X+r.Width*x/10,r.Y,r.X+r.Width*x/10,r.Bottom);for(int y=0;y<=4;y++)g.DrawLine(p,r.X,r.Y+r.Height*y/4,r.Right,r.Y+r.Height*y/4);}
 double ceiling=AutoScale?Math.Max(1024,Values.Where(v=>!double.IsNaN(v)).DefaultIfEmpty(0).Max()*1.15):Ceiling;
 var segments=new List<PointF>();for(int n=0;n<Values.Count;n++){double val=Values[n];if(double.IsNaN(val)){DrawSegment(g,segments,r);segments.Clear();continue;}segments.Add(new PointF(r.Right-(Values.Count-1-n)*r.Width/59f,(float)(r.Bottom-r.Height*Math.Max(0,Math.Min(1,val/ceiling)))));}DrawSegment(g,segments,r);
 }
 void DrawSegment(Graphics g,List<PointF> points,Rectangle r){if(points.Count<2)return;var area=new List<PointF>(points);area.Add(new PointF(points[points.Count-1].X,r.Bottom));area.Add(new PointF(points[0].X,r.Bottom));using(var b=new SolidBrush(Color.FromArgb(35,Accent)))g.FillPolygon(b,area.ToArray());using(var p=new Pen(Accent,1.8f))g.DrawLines(p,points.ToArray());}
}
