 void AddGraphs(Snapshot s){cpu.Add(s.Cpu);ram.Add(s.MemoryPercent);net.Add(s.Receive);disk.Add(s.DiskRead);}
 void UpdateView(){RefreshRecorder();if(current==null)return;bool fresh=current!=lastView;if(fresh){history.Add(current);if(history.Count>60)history.RemoveAt(0);lastView=current;}status.Text=(unreadPressure>0?"["+unreadPressure+" performance alerts — open Command Center]    ":"")+(paused?"PAUSED":"● LIVE")+"    "+current.Processes.Count+" processes    "+current.Processes.Sum(p=>p.Threads)+" threads    Up "+TimeSpan.FromMilliseconds(Native.GetTickCount64()).ToString(@"d\.hh\:mm\:ss")+"    "+current.Time.ToString("HH:mm:ss")+(record?"    ● RECORDING":"")+(current.Warning!=""?"    "+current.Warning:"");
 if(page=="Focus"){UpdateFocus();return;}if(page=="Summary"){UpdateSummary(fresh);UpdateTiles();return;}if(page=="Insights"){RefreshInsights();return;}if(cpu!=null){if(fresh)AddGraphs(current);cpu.Value=current.Cpu.ToString("F1")+"%";cpu.Hint=Environment.ProcessorCount+" logical processors · last 60 samples";ram.Value=current.MemoryPercent.ToString("F1")+"%";ram.Hint=Inventory.Bytes(current.Total-current.Available)+" / "+Inventory.Bytes(current.Total)+" · "+Inventory.Bytes(current.Available)+" available";net.Value=Inventory.Bytes(current.Receive)+"/s";net.Hint="Send "+Inventory.Bytes(current.Send)+"/s · active adapters combined";disk.Value=Inventory.Bytes(current.DiskRead)+(double.IsNaN(current.DiskRead)?"":"/s");disk.Hint="Write "+Inventory.Bytes(current.DiskWrite)+"/s · physical disks combined";gpuLabel.Text=SensorText();cpu.Invalidate();ram.Invalidate();net.Invalidate();disk.Invalidate();sub.Text=cpuName.Length>0?cpuName:"Live system performance";}else if(page=="Processes"||page=="App history")RefreshTable();}
 DataGridView MakeGrid(){var g=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=panel,BorderStyle=BorderStyle.None,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AllowUserToResizeRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,EnableHeadersVisualStyles=false,ColumnHeadersBorderStyle=DataGridViewHeaderBorderStyle.None,CellBorderStyle=DataGridViewCellBorderStyle.SingleHorizontal,GridColor=Color.FromArgb(38,47,58)};g.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Color.FromArgb(30,38,48),ForeColor=muted,Padding=new Padding(8),Font=new Font("Segoe UI",9,FontStyle.Bold)};g.DefaultCellStyle=new DataGridViewCellStyle{BackColor=panel,ForeColor=Color.FromArgb(218,225,237),SelectionBackColor=Color.FromArgb(32,66,83),SelectionForeColor=Color.White,Padding=new Padding(7),Font=new Font("Segoe UI",9)};g.RowTemplate.Height=34;g.ColumnHeadersHeight=40;g.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(21,27,35);return g;}
 void SetColumns(string[] columns){if(grid.Columns.Count==columns.Length&&grid.Columns.Count>0&&grid.Columns[0].HeaderText==columns[0])return;grid.Columns.Clear();foreach(var name in columns)grid.Columns.Add(name,name);}
 Dictionary<string,Tuple<double,long>> appHistory=new Dictionary<string,Tuple<double,long>>();DateTime lastHistory;
 void RefreshTable(){if(grid==null)return;if(page=="Processes"||page=="App history"){if(current==null)return;if(page=="App history"){SetColumns(new[]{"Application","Observed CPU time (s)","Peak working set"});if(lastHistory!=current.Time){double dt=lastHistory==default(DateTime)?0:Math.Min(10,(current.Time-lastHistory).TotalSeconds);foreach(var p in current.Processes){Tuple<double,long> h;if(!appHistory.TryGetValue(p.Name,out h))h=Tuple.Create(0.0,0L);appHistory[p.Name]=Tuple.Create(h.Item1+p.Cpu/100*Environment.ProcessorCount*dt,Math.Max(h.Item2,p.Memory));}lastHistory=current.Time;}grid.Rows.Clear();foreach(var x in appHistory.Where(x=>x.Key.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).OrderByDescending(x=>x.Value.Item1))grid.Rows.Add(x.Key,x.Value.Item1.ToString("F1"),Inventory.Bytes(x.Value.Item2));sub.Text="Observed while this view is open in this session; not Windows historical usage.";return;}
 int selected=grid.SelectedRows.Count>0&&grid.SelectedRows[0].Tag is Proc?((Proc)grid.SelectedRows[0].Tag).Id:-1;int scroll=grid.FirstDisplayedScrollingRowIndex;string sort=grid.SortedColumn==null?"CPU %":grid.SortedColumn.Name;var dir=grid.SortOrder==SortOrder.Ascending?ListSortDirection.Ascending:ListSortDirection.Descending;SetColumns(new[]{"Name","PID","CPU %","Memory (MB)","Threads","Handles","Session"});grid.Rows.Clear();foreach(var p in current.Processes.Where(p=>p.Name.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0||p.Id.ToString()==search.Text)){int index=grid.Rows.Add(p.Name,p.Id,Math.Round(p.Cpu,1),Math.Round(p.Memory/1048576.0,1),p.Threads,p.Handles,p.Session);grid.Rows[index].Tag=p;}grid.Sort(grid.Columns[sort],dir);grid.ClearSelection();foreach(DataGridViewRow row in grid.Rows){if(((Proc)row.Tag).Id==selected){row.Selected=true;break;}}if(scroll>=0&&scroll<grid.Rows.Count)grid.FirstDisplayedScrollingRowIndex=scroll;sub.Text="Click a column to sort · search by name or PID · CPU is a share of the entire machine";
 }else if(inventory!=null){SetColumns(inventory.Columns);grid.Rows.Clear();foreach(var row in (page=="GPU"?GpuRows():inventory.Rows).Where(r=>string.Join(" ",r).IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0))grid.Rows.Add(row);sub.Text=inventory.Note.Length>0?inventory.Note:inventory.Rows.Count+" entries · click Refresh to update";}}
 void LoadInventory(){if(inventoryBusy)return;inventoryBusy=true;int generation=inventoryGeneration;string target=page;sub.Text="Reading Windows inventory…";var worker=new BackgroundWorker();worker.DoWork+=(s,e)=>e.Result=Inventory.Read(target);worker.RunWorkerCompleted+=(s,e)=>{worker.Dispose();if(IsDisposed||generation!=inventoryGeneration)return;inventoryBusy=false;if(e.Error!=null){sub.Text=e.Error.Message;return;}inventory=(Table)e.Result;RefreshTable();};worker.RunWorkerAsync();}
 void LoadHardware(){var w=new BackgroundWorker();w.DoWork+=(s,e)=>{string cpuText="",gpuText="";try{using(var q=new ManagementObjectSearcher("SELECT Name FROM Win32_Processor")){foreach(ManagementObject o in q.Get()){using(o){cpuText=Convert.ToString(o["Name"]);}}}var g=Inventory.Read("GPU");gpuText=string.Join("  ·  ",g.Rows.Where(r=>r.Length==3&&r[1]=="Model").Select(r=>r[2]));}catch{}e.Result=new[]{cpuText,gpuText};};w.RunWorkerCompleted+=(s,e)=>{w.Dispose();if(IsDisposed||e.Error!=null)return;var a=(string[])e.Result;cpuName=a[0];gpuInfo="GPU · "+a[1];};w.RunWorkerAsync();}
 void SampleGpu(){if(gpuBusy)return;gpuBusy=true;var w=new BackgroundWorker();w.DoWork+=(s,e)=>{var vendor=Nvidia.Read();double val=double.NaN;try{using(var q=new ManagementObjectSearcher("SELECT UtilizationPercentage FROM Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine")){q.Options.Timeout=TimeSpan.FromSeconds(5);foreach(ManagementObject o in q.Get()){using(o){double v=Convert.ToDouble(o["UtilizationPercentage"]);val=double.IsNaN(val)?v:Math.Max(val,v);}}}}catch{}e.Result=Tuple.Create(val,vendor);};w.RunWorkerCompleted+=(s,e)=>{w.Dispose();if(IsDisposed)return;gpuBusy=false;if(e.Error==null){var r=(Tuple<double,List<GpuSensor>>)e.Result;gpuValue=r.Item1;sensors=r.Item2;sensorTime=DateTime.Now;}else{sensors.Clear();gpuValue=double.NaN;}gpuNote=double.IsNaN(gpuValue)?"Windows GPU engine usage unavailable":"Busiest Windows GPU engine: "+Math.Min(100,gpuValue).ToString("F1")+"% · sampled every five cycles";if(page=="GPU")RefreshTable();UpdateView();};w.RunWorkerAsync();}
 Label recordingState;Button recordingButton;
 void RefreshRecorder(){if(recordingButton!=null&&!recordingButton.IsDisposed)recordingButton.Text=record?"Stop recording":"Start recording";if(recordingState!=null&&!recordingState.IsDisposed)recordingState.Text=(record?(paused?"Paused with monitoring":"Recording"):"Stopped")+" · "+recording.Count+" / 1,800 samples captured";}
 void BuildRecorder(){var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};flow.Controls.Add(new Label{Text="Record system performance",AutoSize=true,Font=new Font("Segoe UI",20),Margin=new Padding(0,25,0,15)});flow.Controls.Add(new Label{Text="Capture CPU, memory, network and disk samples locally.\r\nRecordings stay in memory until you export them. Maximum: 1,800 samples.\r\nPausing live updates also pauses recording. No process names are exported.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,0,0,25)});var toggle=Button(record?"Stop recording":"Start recording");recordingButton=toggle;recordingState=new Label{AutoSize=true,Margin=new Padding(0,12,0,12)};flow.Controls.Add(recordingState);RefreshRecorder();toggle.Click+=(s,e)=>{if(!record&&recording.Count>0){if(MessageBox.Show(this,"Start a new recording? Export the existing recording first if you want to keep it.","New recording",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;recording.Clear();}record=!record;RefreshRecorder();};flow.Controls.Add(toggle);var b=Button("Export recording CSV");b.Click+=(s,e)=>ExportRecording();flow.Controls.Add(b);content.Controls.Add(flow);sub.Text="A local performance recorder for troubleshooting";}
 void RunTask(){using(var d=new OpenFileDialog{Title="Choose a program to run",Filter="Windows programs (*.exe)|*.exe",CheckFileExists=true}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{Process.Start(new ProcessStartInfo(d.FileName){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(d.FileName)});}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not start program");}}}
 void EndProcess(){if(grid==null||grid.SelectedRows.Count==0||!(grid.SelectedRows[0].Tag is Proc)){MessageBox.Show(this,"Select a process first.");return;}var selected=(Proc)grid.SelectedRows[0].Tag;var denied=new[]{"system","registry","smss","csrss","wininit","winlogon","lsass","services","secure system","memory compression"};if(selected.Id<=4||selected.Id==Process.GetCurrentProcess().Id||selected.Session==0||denied.Contains(selected.Name.ToLowerInvariant())||selected.Start==0){MessageBox.Show(this,"This process is protected by Aster or its identity could not be verified.","Cannot end process");return;}try{using(var p=Process.GetProcessById(selected.Id)){if(p.StartTime.ToUniversalTime().Ticks!=selected.Start)throw new Exception("The selected process has exited. Refresh the list.");bool critical;if(!Native.IsProcessCritical(p.Handle,out critical)||critical)throw new Exception("Windows could not confirm that this process is safe to terminate.");if(MessageBox.Show(this,"End "+selected.Name+" (PID "+selected.Id+")?\r\nUnsaved work in this program will be lost.","End process",MessageBoxButtons.YesNo,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;p.Kill();}StartSample();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Could not end process");}}
 static string Csv(string x){x=x??"";if(x.Length>0&&"=+-@\t\r".IndexOf(x[0])>=0)x="'"+x;return "\""+x.Replace("\"","\"\"")+"\"";}
 void SaveCsv(string name,IEnumerable<string[]> rows){using(var d=new SaveFileDialog{Filter="CSV file (*.csv)|*.csv",FileName="Aster-"+name+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".csv"}){if(d.ShowDialog(this)!=DialogResult.OK)return;try{File.WriteAllLines(d.FileName,rows.Select(row=>string.Join(",",row.Select(Csv))),new System.Text.UTF8Encoding(true));MessageBox.Show(this,"Saved to "+d.FileName,"Export complete");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Export failed");}}}
 void Export(){if(page=="Flight recorder"){ExportRecording();return;}if(grid!=null){var rows=new List<string[]>();rows.Add(grid.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText).ToArray());foreach(DataGridViewRow r in grid.Rows)rows.Add(r.Cells.Cast<DataGridViewCell>().Select(c=>Convert.ToString(c.Value)).ToArray());SaveCsv(page,rows);}else SaveCsv("performance",SampleRows(history));}
 IEnumerable<string[]> SampleRows(IEnumerable<Snapshot> samples){yield return new[]{"Local time","CPU percent","Memory percent","Memory used bytes","Receive bytes per second","Send bytes per second","Disk read bytes per second","Disk write bytes per second"};foreach(var s in samples)yield return new[]{s.Time.ToString("o"),F(s.Cpu),F(s.MemoryPercent),(s.Total-s.Available).ToString(),F(s.Receive),F(s.Send),F(s.DiskRead),F(s.DiskWrite)};}
 string F(double v){return double.IsNaN(v)?"Unavailable":v.ToString("F2",System.Globalization.CultureInfo.InvariantCulture);}
 void ExportRecording(){if(recording.Count==0){MessageBox.Show(this,"Start a recording first.");return;}SaveCsv("recording",SampleRows(recording));}
}
